/**
 * @file API Zod package entry point — re-exports all generated Zod schemas and TypeScript types.
 *
 * This package provides runtime request/response validation schemas (Zod) and their
 * corresponding TypeScript types, auto-generated from the OpenAPI spec by Orval.
 * It is consumed by the API server to validate incoming requests and by the
 * frontend to ensure type safety when calling the API.
 *
 * ## What is generated here?
 * - `generated/api.ts` — Zod schemas for every API endpoint (request/response bodies, query params)
 * - `generated/types/` — TypeScript interfaces corresponding to the Zod schemas
 *
 * ## Code Generation
 * These files are generated by Orval (see `shared/api-spec/orval.config.ts`).
 * Do NOT edit them manually — changes will be overwritten on the next `orval` run.
 * Instead, update the OpenAPI spec (`openapi.yaml`) and regenerate.
 *
 * ## Usage
 * ```ts
 * import { HealthCheckResponse, HealthStatus } from "@repo/api-zod";
 *
 * // Runtime validation
 * const parsed = HealthCheckResponse.parse(unknownData);
 *
 * // Type usage
 * const status: HealthStatus = { status: "ok" };
 * ```
 */
export * from "./generated/api";
export * from "./generated/types";
